const janeiro: SantoDoDia[] = [
  { day: 1, title: "Santa Maria, Mae de Deus", image: "/santos/2025/01-01.jpg", source: "https://santo.cancaonova.com/santo/santa-maria-mae-de-deus/?sDia=1&sMes=1&sAno=2025", description: "A Solenidade de Santa Maria, Mãe de Deus, é a primeira festa mariana que apareceu na Igreja ocidental. Sua origem remonta à cidade de Roma, onde, no século VI, um concílio foi realizado para condenar o nestorianismo, que negava a maternidade divina de Maria. A festa, então chamada de 'Maternidade Divina de Nossa Senhora', era celebrada no dia 1º de janeiro, oitava do Natal, para enfatizar a íntima ligação entre a Virgem e seu Filho. Em 1931, o Papa Pio XI instituiu a festa no dia 11 de outubro, mas, com a reforma do Concílio Vaticano II, a celebração foi restaurada para 1º de janeiro, com o título de 'Solenidade de Santa Maria, Mãe de Deus'." },
  { day: 2, title: "Santos Basilio Magno e Gregorio de Nazianzeno", image: "/santos/2025/01-02.jpg", source: "https://santo.cancaonova.com/santo/santos-basilio-magno-e-gregorio-de-nazianzeno/?sDia=2&sMes=1&sAno=2025", description: "São Basílio Magno e São Gregório de Nazianzo, ambos Doutores da Igreja, viveram no século IV e são celebrados juntos em 2 de janeiro. Nascidos na Capadócia (atual Turquia), eles se tornaram amigos íntimos durante seus estudos em Atenas e seguiram a vida monástica juntos, com Basílio fundando uma comunidade monástica e Gregório se juntando a ele. Basílio tornou-se bispo de Cesareia e combateu a heresia do arianismo, enquanto Gregório, conhecido como 'o Teólogo', presidiu o Concílio de Constantinopla e foi fundamental na defesa da divindade do Espírito Santo. A amizade e colaboração deles na fé os tornaram figuras centrais entre os Padres Capadócios, e seu legado teológico continua a influenciar a Igreja." },
  { day: 3, title: "Santa Genoveva, virgem que tudo entregava a Deus", image: "/santos/2025/01-03.jpg", source: "https://santo.cancaonova.com/santo/santa-genoveva-virgem-que-tudo-entregava-a-deus/?sDia=3&sMes=1&sAno=2025", description: "Santa Genoveva, padroeira de Paris, nasceu por volta de 422 em Nanterre, França. Desde cedo, dedicou sua vida a Deus, sendo consagrada por São Germano de Auxerre. Após a morte dos pais, mudou-se para Paris, onde viveu uma vida de austeridade, oração e caridade. Em 451, durante a invasão dos hunos de Átila, ela convenceu o povo de Paris a não abandonar a cidade, confiando na proteção divina, e a cidade foi poupada. Mais tarde, organizou o abastecimento de alimentos para a população faminta. Santa Genoveva faleceu por volta de 502, e suas relíquias, embora profanadas na Revolução Francesa, continuam a ser veneradas em Paris." },
  { day: 4, title: "Santa Angela de Foligno, um exemplo de conversao", image: "/santos/2025/01-04.jpg", source: "https://santo.cancaonova.com/santo/santa-angela-de-foligno/?sDia=4&sMes=1&sAno=2025", description: "Santa Ângela de Foligno nasceu em 1248, em Foligno, Itália, em uma família rica. Viveu uma vida mundana até os 37 anos, quando, após a morte de seus pais, marido e filhos, passou por uma profunda conversão. Tornou-se franciscana secular, dedicando-se à penitência e à caridade. Suas experiências místicas foram registradas em sua autobiografia, o 'Livro da Bem-Aventurada Ângela', uma das obras místicas mais importantes da Idade Média. Faleceu em 1309 e foi canonizada em 2013 pelo Papa Francisco." },
  { day: 5, title: "Sao Joao Nepomuceno Neumann, bispo de Filadelfia", image: "/santos/2025/01-05.jpg", source: "https://santo.cancaonova.com/santo/sao-joao-nepomuceno-neumann/?sDia=5&sMes=1&sAno=2025", description: "São João Nepomuceno Neumann nasceu na Boêmia (atual República Tcheca) em 1811. Devido ao grande número de padres em sua terra natal, emigrou para os Estados Unidos, onde foi ordenado sacerdote em Nova Iorque. Ingressou na Congregação dos Redentoristas e, em 1852, foi nomeado Bispo da Filadélfia. Destacou-se por expandir o sistema de escolas católicas e por sua dedicação aos imigrantes. Faleceu em 1860 e foi canonizado em 1977, sendo o único homem estadunidense a ser declarado santo." },
  { day: 6, title: "Epifania do Senhor, dia que lembramos de Santos Reis", image: "/santos/2025/01-06.jpg", source: "https://santo.cancaonova.com/santo/epifania-do-senhor-dia-que-lembramos-de-santos-reis/?sDia=6&sMes=1&sAno=2025", description: "A Epifania do Senhor, celebrada em 6 de janeiro, comemora a manifestação de Jesus Cristo como o Messias de Israel, Filho de Deus e Salvador do mundo. A festa inclui a adoração de Jesus pelos Reis Magos do Oriente, o batismo de Jesus no rio Jordão e as bodas de Caná. A visita dos Magos, que representam as nações pagãs, significa que a salvação é oferecida a todos os povos. No Brasil, a data é popularmente conhecida como o 'Dia de Reis'." },
  { day: 7, title: "Sao Raimundo de Penafort, eximio na ciencia do Direito Canonico", image: "/santos/2025/01-07.jpg", source: "https://santo.cancaonova.com/santo/sao-raimundo-de-penafort/?sDia=7&sMes=1&sAno=2025", description: "São Raimundo de Penafort, nascido por volta de 1175 na Catalunha, Espanha, foi um proeminente frade dominicano e canonista. Doutor em direito civil e canônico, foi chamado a Roma pelo Papa Gregório IX para compilar as 'Decretais de Gregório IX', uma obra fundamental para o Direito Canônico. Foi também Mestre Geral da Ordem Dominicana e dedicou-se à evangelização de judeus e muçulmanos. É o padroeiro dos advogados canônicos." },
  { day: 8, title: "Sao Severino", image: "/santos/2025/01-08.jpg", source: "https://santo.cancaonova.com/santo/sao-severino/?sDia=8&sMes=1&sAno=2025", description: "São Severino, conhecido como o Apóstolo de Nórica (atual Áustria), viveu no século V, um período de grande instabilidade na Europa devido às invasões bárbaras. Nascido em uma família nobre de Roma, renunciou à sua herança para viver como monge no Oriente. Mais tarde, estabeleceu-se na região do Danúbio, onde fundou mosteiros que se tornaram centros de fé, cultura e refúgio para as populações locais. Tinha o dom da profecia e era respeitado tanto pelos romanos quanto pelos bárbaros. Faleceu em 482." },
  { day: 9, title: "Santo Andre Corsini", image: "/santos/2025/01-09.jpg", source: "https://santo.cancaonova.com/santo/santo-andre-corsini/?sDia=9&sMes=1&sAno=2025", description: "Santo André Corsini nasceu em Florença, Itália, em 1302, em uma família nobre. Após uma juventude rebelde, converteu-se e ingressou na Ordem Carmelita, dedicando-se à oração, penitência e caridade. Em 1349, foi nomeado Bispo de Fiesole, cargo que inicialmente recusou por humildade. Como bispo, foi um pastor exemplar, conhecido por sua caridade e zelo apostólico. Faleceu em 1374 e foi canonizado em 1629. É padroeiro de Florença e Fiesole." },
  { day: 10, title: "Frei Goncalo de Amarante, presbitero de Braga", image: "/santos/2025/01-10.jpg", source: "https://santo.cancaonova.com/santo/frei-goncalo-de-amarante/?sDia=10&sMes=1&sAno=2025", description: "São Gonçalo de Amarante, nascido por volta de 1187 em Portugal, foi um sacerdote dominicano conhecido por sua vida de peregrinação e caridade. Após peregrinar por Roma e pela Terra Santa, estabeleceu-se em Amarante, onde se dedicou à evangelização e à construção de uma ponte sobre o rio Tâmega. É popularmente invocado como 'casamenteiro' e conhecido pela 'dança de São Gonçalo'. Faleceu em 1262 e, embora beatificado, é venerado como santo." },
  { day: 11, title: "Santo Higino, o nono Papa da Igreja Catolica", image: "/santos/2025/01-11.jpg", source: "https://santo.cancaonova.com/santo/santo-higino/?sDia=11&sMes=1&sAno=2025", description: "Santo Higino, o nono Papa da Igreja, liderou a Igreja por volta do ano 138 a 142. Nascido em Atenas, Grécia, e filho de um filósofo, seu pontificado foi marcado pela luta contra as heresias gnósticas, que ameaçavam a fé cristã. Ele estabeleceu as Ordens Menores para melhor organizar a hierarquia eclesiástica e instituiu a figura dos padrinhos no batismo. Acredita-se que tenha sido martirizado durante a perseguição do imperador Antonino Pio." },
  { day: 12, title: "Sao Bernardo de Corleone", image: "/santos/2025/01-12.jpg", source: "https://santo.cancaonova.com/santo/sao-bernardo-de-corleone/?sDia=12&sMes=1&sAno=2025", description: "São Bernardo de Corleone, nascido Filippo Latini em 1605 na Sicília, foi um frade capuchinho. Em sua juventude, era um espadachim habilidoso e de temperamento violento. Após um duelo, converteu-se e ingressou na Ordem dos Frades Menores Capuchinhos. Destacou-se pela humildade, oração e penitência, e por sua dedicação aos doentes e pobres. Faleceu em 1667 e foi canonizado em 2001 pelo Papa João Paulo II." },
  { day: 13, title: "Santo Hilario de Poitiers, o Atanasio do Ocidente", image: "/santos/2025/01-13.jpg", source: "https://santo.cancaonova.com/santo/santo-hilario-de-poitiers/?sDia=13&sMes=1&sAno=2025", description: "Santo Hilário de Poitiers, nascido em 315 na Gália (atual França), foi um bispo e Doutor da Igreja. De família pagã, converteu-se ao cristianismo na idade adulta e tornou-se bispo de Poitiers. Foi um grande defensor da fé contra a heresia ariana, que negava a divindade de Cristo, o que lhe rendeu o título de 'Atanásio do Ocidente'. Exilado por sua fé, continuou a escrever e a defender a doutrina da Trindade. Faleceu em 367." },
  { day: 14, title: "Santa Elisabete Ana Bayley Seton", image: "/santos/2025/01-14.jpg", source: "https://santo.cancaonova.com/santo/santa-elisabete-ana-bayley-seton-obediente-ao-senhor/?sDia=14&sMes=1&sAno=2025", description: "Santa Elisabete Ana Bayley Seton, a primeira santa nascida nos Estados Unidos, nasceu em 1774 em Nova Iorque. Após a morte de seu marido, converteu-se ao catolicismo, enfrentando oposição de sua família. Em 1809, fundou as Irmãs da Caridade de São José, a primeira comunidade religiosa feminina nos Estados Unidos, dedicada à educação de crianças pobres. Faleceu em 1821 e é a padroeira das escolas católicas." },
  { day: 15, title: "Santo Amaro, amigo de Sao Bento", image: "/santos/2025/01-15.jpg", source: "https://santo.cancaonova.com/santo/santo-amaro/?sDia=15&sMes=1&sAno=2025", description: "Santo Amaro foi um dos primeiros e mais fiéis discípulos de São Bento de Núrsia. Nascido em Roma, ingressou na vida monástica aos 12 anos. É conhecido por sua obediência e pelo milagre de ter andado sobre as águas para salvar seu primo, São Plácido, a pedido de São Bento. Sucedeu a São Bento no mosteiro de Subiaco e faleceu em 567. É invocado contra diversas doenças." },
  { day: 16, title: "Sao Berardo e companheiros martires", image: "/santos/2025/01-16.jpg", source: "https://santo.cancaonova.com/santo/sao-berardo-e-companheiros-martires/?sDia=16&sMes=1&sAno=2025", description: "São Berardo e seus companheiros, Otone, Pedro, Acúrsio e Adjuto, foram os primeiros mártires da Ordem Franciscana. Enviados por São Francisco de Assis para evangelizar os muçulmanos no Marrocos, eles pregaram abertamente em Marraquexe em 1220. Após serem presos, torturados e se recusarem a negar a fé, foram decapitados. Seu martírio inspirou muitos, incluindo Santo Antônio de Lisboa (Santo Antônio de Pádua), a se juntarem à Ordem Franciscana." },
  { day: 17, title: "Santo Antao, o santo que vivia no Cemiterio", image: "/santos/2025/01-17.jpg", source: "https://santo.cancaonova.com/santo/santo-antao/?sDia=17&sMes=1&sAno=2025", description: "Santo Antão, conhecido como o 'Pai dos Monges', nasceu no Egito em 251. Após a morte dos pais, distribuiu seus bens aos pobres e retirou-se para o deserto, onde viveu em oração e penitência. Passou um período vivendo em um cemitério, onde enfrentou tentações demoníacas. Sua vida de eremita atraiu muitos discípulos, dando origem às primeiras comunidades monásticas. Faleceu em 356, aos 105 anos." },
  { day: 18, title: "Santa Prisca, a protomartir romana", image: "/santos/2025/01-18.jpg", source: "https://santo.cancaonova.com/santo/santa-prisca/?sDia=18&sMes=1&sAno=2025", description: "Santa Prisca é venerada como a primeira mártir do Ocidente. Segundo a tradição, foi batizada por São Pedro em Roma aos 13 anos. Recusando-se a adorar deuses pagãos, foi martirizada por sua fé. Embora haja incertezas históricas sobre a data exata de seu martírio, sua devoção é antiga. Ela é por vezes identificada com a Prisca mencionada por São Paulo. Uma antiga igreja no Monte Aventino, em Roma, é dedicada a ela." },
  { day: 19, title: "Sao Canuto", image: "/santos/2025/01-19.jpg", source: "https://santo.cancaonova.com/santo/sao-canuto-contribuiu-para-a-evangelizacao/?sDia=19&sMes=1&sAno=2025", description: "São Canuto IV, rei da Dinamarca no século XI, foi um monarca devoto que trabalhou para fortalecer o cristianismo em seu país. Ele promoveu a construção de igrejas e mosteiros e defendeu a moralidade cristã. Sua tentativa de impor dízimos e outras reformas gerou uma revolta da nobreza. Foi assassinado em 1086 enquanto rezava em uma igreja. Canonizado em 1101, é o padroeiro da Dinamarca." },
  { day: 20, title: "Sao Sebastiao, o soldado martirizado", image: "/santos/2025/01-20.jpg", source: "https://santo.cancaonova.com/santo/sao-sebastiao/?sDia=20&sMes=1&sAno=2025", description: "São Sebastião foi um soldado romano e mártir cristão do século III. Capitão da Guarda Pretoriana, usava sua posição para ajudar os cristãos perseguidos. Ao ser descoberto, foi condenado à morte por flechadas. Sobrevivendo milagrosamente, apresentou-se novamente ao imperador para interceder pelos cristãos, sendo então espancado até a morte. É padroeiro contra a peste, a fome e a guerra." },
  { day: 21, title: "Santa Ines, a jovem virgem e martir", image: "/santos/2025/01-21.jpg", source: "https://santo.cancaonova.com/santo/santa-ines/?sDia=21&sMes=1&sAno=2025", description: "Santa Inês, virgem e mártir romana, viveu no século III. Aos 12 anos, recusou casar-se com o filho do prefeito de Roma, afirmando ser esposa de Cristo. Por sua fé, foi submetida a diversas torturas e, finalmente, decapitada. É um símbolo de pureza e castidade, e seu nome está associado à palavra 'agnus' (cordeiro), animal com o qual é frequentemente representada." },
  { day: 22, title: "Sao Vicente de Saragoca, padroeiro de Lisboa", image: "/santos/2025/01-22.jpg", source: "https://santo.cancaonova.com/santo/sao-vicente-de-saragoca-padroeiro-de-lisboa/?sDia=22&sMes=1&sAno=2025", description: "São Vicente de Saragoça, diácono e mártir do século III, é um dos mártires mais célebres da Península Ibérica. Nascido em Huesca, Espanha, foi educado pelo bispo Valério de Saragoça e tornou-se seu diácono, encarregado da pregação. Durante a perseguição de Diocleciano, foi preso e brutalmente torturado em Valência por sua fé, mas permaneceu inabalável. Faleceu em 304 e é padroeiro de Lisboa e dos vinicultores." },
  { day: 23, title: "Santo Ildefonso, o bispo dedicado a Virgem Maria", image: "/santos/2025/01-23.jpg", source: "https://santo.cancaonova.com/santo/santo-ildefonso/?sDia=23&sMes=1&sAno=2025", description: "Santo Ildefonso foi um bispo de Toledo do século VII, conhecido por sua profunda devoção à Virgem Maria. Ele defendeu a virgindade perpétua de Maria e, segundo a tradição, recebeu dela uma casula em uma aparição. Foi um escritor prolífico e uma figura importante na Igreja Visigótica na Espanha. Faleceu em 667." },
  { day: 24, title: "Sao Francisco de Sales, patrono dos escritores e dos jornalistas", image: "/santos/2025/01-24.jpg", description: "Hoje, a Igreja celebra o dia de São Francisco de Sales, patrono dos escritores e dos jornalistas devido ao estilo e ao conteúdo de seus escritos.", source: "https://santo.cancaonova.com/santo/sao-francisco-de-sales/?sDia=24&sMes=1&sAno=2025" },
  { day: 25, title: "Conversao de Sao Paulo, apostolo", image: "/santos/2025/01-25.jpg", description: "Origens Saulo, que depois tomou o nome de Paulo, nasceu em Tarso, capital da Cilícia. Da tribo de Benjamim, era judeu de nação. Logo, ele recebeu também o título de cidadão romano. O seu pai pertencia à seita dos fariseus, ou seja, pertencia ao grupo dos judeus que exerciam a profissão de observar a lei e de seguir a moral mais severa.", source: "https://santo.cancaonova.com/santo/conversao-de-sao-paulo/?sDia=25&sMes=1&sAno=2025" },
  { day: 26, title: "Santos Timoteo e Tito, bispos", image: "/santos/2025/01-26.jpg", source: "https://santo.cancaonova.com/santo/santos-timoteo-e-tito-bispos/?sDia=26&sMes=1&sAno=2025", description: "São Timóteo e São Tito foram discípulos e fiéis colaboradores de São Paulo Apóstolo. Timóteo, filho de mãe judia e pai grego, foi o primeiro bispo de Éfeso e é o destinatário de duas cartas de Paulo. Tito, de origem grega, foi bispo de Creta e um mediador de paz na comunidade de Corinto. Ambos são exemplos de dedicação pastoral e fidelidade ao Evangelho, e suas memórias são celebradas em 26 de janeiro." },
  { day: 27, title: "Santa Angela Merici, fundadora da Companhia de Santa Ursula", image: "/santos/2025/01-27.jpg", source: "https://santo.cancaonova.com/santo/santa-angela-merici-fundadora/?sDia=27&sMes=1&sAno=2025", description: "Santa Ângela de Mérici, nascida em 1474 na Itália, foi a fundadora da Companhia de Santa Úrsula (Ursulinas), a primeira ordem religiosa feminina dedicada à educação de meninas fora da clausura. Órfã desde jovem, tornou-se franciscana secular e dedicou sua vida à caridade e à formação de jovens. Sua obra foi pioneira na educação feminina e na santificação da família. Faleceu em 1540 e foi canonizada em 1807." },
  { day: 28, title: "Sao Tomas de Aquino, o Doctor Angelicus", image: "/santos/2025/01-28.jpg", source: "https://santo.cancaonova.com/santo/sao-tomas-de-aquino/?sDia=28&sMes=1&sAno=2025", description: "São Tomás de Aquino, frade dominicano do século XIII, é um dos mais influentes teólogos e filósofos da história da Igreja. Conhecido como o 'Doutor Angélico', sua obra-prima, a 'Suma Teológica', harmoniza a fé cristã com a filosofia de Aristóteles. Ele defendia que a fé e a razão são complementares e ambas levam à verdade. É padroeiro das escolas e universidades católicas." },
  { day: 29, title: "Sao Constancio, bispo de Perugia", image: "/santos/2025/01-29.jpg", source: "https://santo.cancaonova.com/santo/sao-constancio-bispo/?sDia=29&sMes=1&sAno=2025", description: "São Constâncio foi o primeiro bispo de Perúgia, na Itália, no século II. Durante a perseguição do imperador Marco Aurélio, foi preso e torturado por sua fé, mas sobreviveu milagrosamente a vários suplícios. Converteu seus próprios guardas e, após ser capturado novamente, foi decapitado em 170 d.C. É um dos padroeiros de Perúgia." },
  { day: 30, title: "Santa Jacinta Marescotti, um exemplo de dedicacao total a Deus", image: "/santos/2025/01-30.jpg", source: "https://santo.cancaonova.com/santo/santa-jacinta-marescotti/?sDia=30&sMes=1&sAno=2025", description: "Santa Jacinta Marescotti, nascida em 1585 em uma nobre família romana, viveu uma juventude de vaidade e luxo. Após uma decepção amorosa, entrou para um convento franciscano, mas continuou a viver de forma mundana. Uma grave doença a levou a uma profunda conversão. A partir de então, dedicou-se à oração, penitência e caridade, tornando-se um exemplo de humildade. Faleceu em 1640 e foi canonizada em 1807." },
  { day: 31, title: "Sao Joao Bosco, fundador da Sociedade Salesiana", image: "/santos/2025/01-31.jpg", source: "https://santo.cancaonova.com/santo/sao-joao-bosco/?sDia=31&sMes=1&sAno=2025", description: "São João Bosco, conhecido como Dom Bosco, foi um sacerdote italiano do século XIX que dedicou sua vida à educação de jovens pobres e abandonados. Fundou a Sociedade Salesiana, as Filhas de Maria Auxiliadora e os Cooperadores Salesianos. Seu método educativo, o 'Sistema Preventivo', baseava-se na razão, na religião e no amor. É considerado o 'Pai e Mestre da Juventude' e padroeiro dos jovens e estudantes." },
];

const fevereiro: SantoDoDia[] = [
  { day: 1, title: "Santa Veridiana, protetora e intercessora das presidiarias", image: "/santos/2025/02-01.jpg", source: "https://santo.cancaonova.com/santo/santa-veridiana/?sDia=1&sMes=2&sAno=2025", description: "Santa Veridiana nasceu em 1182, em Florença, Itália. De família nobre, dedicou sua vida à caridade e à penitência. Após peregrinar a Compostela e a Roma, viveu 34 anos reclusa em uma cela, onde recebeu a visita de São Francisco de Assis. É invocada como protetora das presidiárias, por sua vida de reclusão voluntária em busca de Deus. Faleceu em 1242." },
  { day: 2, title: "Apresentacao do Senhor no Templo: Jesus e a nossa Luz", image: "/santos/2025/02-02.png", source: "https://santo.cancaonova.com/santo/apresentacao-do-senhor/?sDia=2&sMes=2&sAno=2025", description: "A Apresentação do Senhor, celebrada em 2 de fevereiro, recorda o dia em que Maria e José levaram o Menino Jesus ao Templo de Jerusalém, 40 dias após seu nascimento, para cumprir a Lei de Moisés. Lá, Simeão e Ana, inspirados pelo Espírito Santo, reconheceram Jesus como o Messias prometido, a 'luz para iluminar as nações'. A festa é também conhecida como Nossa Senhora das Candeias ou da Purificação." },
  { day: 3, title: "Sao Bras de Sebaste, medico e protetor da garganta", image: "/santos/2025/02-03.jpg", source: "https://santo.cancaonova.com/santo/sao-bras-de-sebaste/?sDia=3&sMes=2&sAno=2025", description: "São Brás foi um médico e bispo de Sebaste, na Armênia, no século IV. Dedicou sua vida a cuidar dos doentes tanto no corpo quanto na alma. Durante a perseguição do imperador Licínio, refugiou-se em uma caverna, mas foi descoberto e preso. É conhecido por ter salvo um menino que se engasgou com uma espinha de peixe. Foi martirizado em 316 e é venerado como o protetor contra os males da garganta." },
  { day: 4, title: "Sao Joao de Brito, santo portugues e grande evangelizador na India", image: "/santos/2025/02-04.jpg", source: "https://santo.cancaonova.com/santo/sao-joao-de-brito/?sDia=4&sMes=2&sAno=2025", description: "São João de Brito foi um missionário jesuíta português do século XVII. Nascido em uma família nobre de Lisboa, renunciou a uma vida de privilégios para evangelizar na Índia. Adotou os costumes e a língua locais para melhor comunicar o Evangelho. Enfrentou perseguições e foi preso, mas continuou sua missão com fervor. Foi martirizado em 1693 e é conhecido como o 'São Francisco Xavier Português'." },
  { day: 5, title: "Santa Agueda, protetora dos seios e intercessora das virgens", image: "/santos/2025/02-05.jpg", source: "https://santo.cancaonova.com/santo/santa-agueda-protetora-dos-seios-e-intercessora-das-virgens/?sDia=5&sMes=2&sAno=2025", description: "Santa Águeda, virgem e mártir do século III, nasceu na Sicília em uma família nobre. Consagrou sua virgindade a Deus e, por se recusar a casar com o cônsul romano Quintianus e a renunciar à sua fé, foi cruelmente torturada, tendo seus seios arrancados. É venerada como protetora contra doenças de mama, queimaduras e erupções vulcânicas. Faleceu em 251." },
  { day: 6, title: "Sao Paulo Miki e companheiros martires, padroeiros do Japao", image: "/santos/2025/02-06.jpg", source: "https://santo.cancaonova.com/santo/sao-paulo-miki-e-companheiros-martires/?sDia=6&sMes=2&sAno=2025", description: "São Paulo Miki e seus 25 companheiros foram martirizados no Japão em 1597. Paulo Miki, um jesuíta japonês, e seus companheiros, que incluíam franciscanos e leigos, foram crucificados em Nagasaki durante a perseguição aos cristãos. Eles são um testemunho da fé cristã no Japão e foram canonizados em 1862. São os padroeiros do Japão." },
  { day: 7, title: "Sao Ricardo, governante caridoso com tres filhos santos", image: "/santos/2025/02-07.jpg", source: "https://santo.cancaonova.com/santo/sao-ricardo-governante-caridoso-com-filhos-santos/?sDia=7&sMes=2&sAno=2025", description: "São Ricardo, um governante de Wessex no século VIII, foi um exemplo de caridade e justiça. Pai de três santos, São Winebaldo, São Vilibaldo e Santa Valburga, abdicou de sua posição para se dedicar à vida monástica. Iniciou uma peregrinação a Roma e à Terra Santa, mas faleceu em Lucca, Itália, em 722. Seu túmulo tornou-se um local de veneração, e ele é conhecido como o 'Rei Santo'." },
  { day: 8, title: "Santo Irmao Miguel Febres, educador e patrono dos pedagogos", image: "/santos/2025/02-08.jpg", source: "https://santo.cancaonova.com/santo/santo-irmao-miguel-febres-educador-e-patrono-dos-pedagogos/?sDia=8&sMes=2&sAno=2025", description: "Santo Irmão Miguel Febres Cordero, nascido no Equador em 1854, foi um religioso dos Irmãos das Escolas Cristãs (La Salle). Apesar de uma deficiência física, tornou-se um renomado educador e escritor, autor de diversos livros didáticos. Foi o primeiro santo equatoriano e é o patrono dos pedagogos. Faleceu na Espanha em 1910 e foi canonizado em 1984." },
  { day: 9, title: "Beata Eusebia Palomino Yenes, irma salesiana de Dom Bosco", image: "/santos/2025/02-09.jpg", source: "https://santo.cancaonova.com/santo/beata-eusebia-palomino-yenes/?sDia=9&sMes=2&sAno=2025", description: "Beata Eusébia Palomino Yenes, nascida na Espanha em 1899, foi uma irmã salesiana. De família humilde, trabalhou desde cedo para ajudar no sustento da casa. Ingressou na Congregação das Filhas de Maria Auxiliadora, onde se dedicou aos trabalhos mais simples, como cozinheira e porteira. Era conhecida por sua profunda vida de oração e por seu dom de profecia. Faleceu em 1935 e foi beatificada em 2004 pelo Papa João Paulo II." },
  { day: 10, title: "Santa Escolastica ensina: \"Quem ama mais pode mais\"", image: "/santos/2025/02-10.jpg", source: "https://santo.cancaonova.com/santo/santa-escolastica/?sDia=10&sMes=2&sAno=2025", description: "Santa Escolástica, irmã gêmea de São Bento de Núrsia, nasceu na Itália em 480. Consagrou sua vida a Deus e fundou o ramo feminino da Ordem Beneditina. É conhecida por seu profundo diálogo espiritual com seu irmão e pelo milagre da tempestade, que, segundo a tradição, ela provocou com suas orações para que São Bento permanecesse mais tempo com ela. Faleceu em 547 e é padroeira das monjas e das crianças com convulsões." },
  { day: 11, title: "Nossa Senhora de Lourdes, intercessora dos doentes", image: "/santos/2025/02-11.jpg", source: "https://santo.cancaonova.com/santo/nossa-senhora-de-lourdes-intercessora-dos-doentes/?sDia=11&sMes=2&sAno=2025", description: "Nossa Senhora de Lourdes refere-se às 18 aparições da Virgem Maria a Santa Bernadette Soubirous em 1858, na gruta de Massabielle, em Lourdes, França. Nessas aparições, a Virgem se identificou como a 'Imaculada Conceição', pediu oração e penitência pela conversão dos pecadores, e fez brotar uma fonte de água milagrosa. Lourdes tornou-se um dos maiores santuários marianos do mundo, um lugar de cura e de fé para milhões de peregrinos." },
  { day: 12, title: "Santa Eulalia, adolescente torturada e martirizada", image: "/santos/2025/02-12.jpg", source: "https://santo.cancaonova.com/santo/santa-eulalia/?sDia=12&sMes=2&sAno=2025", description: "Santa Eulália foi uma jovem virgem mártir da Espanha do século III. Aos 12 anos, durante a perseguição de Diocleciano, ela se apresentou voluntariamente às autoridades romanas para protestar contra a perseguição aos cristãos. Por se recusar a renegar sua fé, foi submetida a treze torturas brutais antes de ser decapitada. Sua coragem e fé inabalável a tornaram uma das mártires mais veneradas da Espanha." },
  { day: 13, title: "Sao Martiniano, intercessor pela vivencia da castidade", image: "/santos/2025/02-13.jpg", source: "https://santo.cancaonova.com/santo/sao-martiniano/?sDia=13&sMes=2&sAno=2025", description: "São Martiniano foi um eremita do século IV, conhecido por sua vida de oração e penitência em Cesareia, na Palestina. É venerado como um grande intercessor pela vivência da castidade, devido à sua famosa luta contra a tentação. A história mais conhecida sobre ele narra como ele resistiu à sedução de uma cortesã, convertendo-a à fé. Sua vida é um testemunho da busca pela pureza e da força da graça de Deus." },
  { day: 14, title: "Santos Cirilo e Metodio, os apostolos dos eslavos", image: "/santos/2025/02-14.jpg", source: "https://santo.cancaonova.com/santo/santos-cirilo-e-metodio/?sDia=14&sMes=2&sAno=2025", description: "São Cirilo e São Metódio, irmãos gregos do século IX, são conhecidos como os 'Apóstolos dos Eslavos'. Eles criaram o alfabeto glagolítico para traduzir as Sagradas Escrituras e os textos litúrgicos para a língua eslava, permitindo a evangelização dos povos eslavos em sua própria língua. Enfrentaram oposição, mas receberam o apoio do Papa. São co-patronos da Europa." },
  { day: 15, title: "Sao Claudio La Colombiere, apostolo do Sagrado Coracao de Jesus", image: "/santos/2025/02-15.jpg", description: "Origem Nascido no sul da França, São Cláudio fez parte de uma família de posses. Teve seis irmãos, dentre eles três também foram sacerdotes ou religiosos. Em sua juventude, frequentou uma escola da Companhia de Jesus e ingressou na ordem aos 17 anos.", source: "https://santo.cancaonova.com/santo/sao-claudio-la-colombiere/?sDia=15&sMes=2&sAno=2025" },
  { day: 16, title: "Santa Juliana, martir por nao aceitar o casamento pagao", image: "/santos/2025/02-16.jpg", source: "https://santo.cancaonova.com/santo/santa-juliana/?sDia=16&sMes=2&sAno=2025", description: "Santa Juliana de Nicomédia, mártir do século IV, é um exemplo de fé inabalável. Cristã desde a infância, recusou casar-se com um nobre pagão, exigindo sua conversão. Por isso, foi denunciada, presa e submetida a cruéis torturas. Manteve-se firme em sua fé e foi decapitada em 304. É invocada por doentes e mulheres grávidas." },
  { day: 17, title: "Sete Santos fundadores dos Servitas: ministros da unidade e da paz", image: "/santos/2025/02-17.jpg", description: "Fundação da Instituição Religiosa A Ordem dos Frades Servos de Maria (OSM), cujos membros são conhecidos como “Servitas”, foi fundada em Florença, Itália, em 1233, por sete ricos comerciantes.", source: "https://santo.cancaonova.com/santo/sete-santos-fundadores-dos-servitas/?sDia=17&sMes=2&sAno=2025" },
  { day: 18, title: "Sao Teotonio, o primeiro santo portugues e fundador do Mosteiro Santa Cruz", image: "/santos/2025/02-18.jpg", description: "Hoje, a Igreja celebra o dia de São Teotônio, que foi o primeiro santo português e fundador do Mosteiro Santa Cruz, reformador da vida religiosa.", source: "https://santo.cancaonova.com/santo/sao-teotonio/?sDia=18&sMes=2&sAno=2025" },
  { day: 19, title: "Sao Conrado, exemplo de arrependimento diante da injustica", image: "/santos/2025/02-19.jpg", description: "Pecado que tornou-se conversão Para caçar lebres, esse homem colocou fogo numa floresta, gerando grave prejuízo. Por isso, o governador do local iniciou a procura do culpado. Ao encontrar um suspeito, logo o condenou à morte. Quando Conrado soube que um inocente morreria em seu lugar, decidiu confessar o crime. Isso custou caro, a ponto dele tornar-se muito pobre, mas quitou a sua pendência.", source: "https://santo.cancaonova.com/santo/sao-conrado/?sDia=19&sMes=2&sAno=2025" },
  { day: 20, title: "Francisco e Jacinta Marto: os santos pastorinhos", image: "/santos/2025/02-20.jpg", description: "Hoje, a Igreja celebra o dia dos santos pastorinhos de Fátima, Francisco e Jacinta Marto, e canonizou as duas primeiras crianças não mártires.", source: "https://santo.cancaonova.com/santo/francisco-e-jacinta/?sDia=20&sMes=2&sAno=2025" },
  { day: 21, title: "Sao Pedro Damiao, o corajoso bispo e doutor da Igreja", image: "/santos/2025/02-21.jpg", description: "Hoje, a Igreja celebra o dia de São Pedro Damião, que foi um corajoso religioso, discerniu sua vocação à vida religiosa e foi bispo e doutor da Igreja.", source: "https://santo.cancaonova.com/santo/sao-pedro-damiao-o-corajoso-bispo-e-doutor-da-igreja/?sDia=21&sMes=2&sAno=2025" },
  { day: 22, title: "Catedra de Sao Pedro: de onde o Papa governa a Igreja", image: "/santos/2025/02-22.jpg", description: "Festa para uma cadeira? É muito mais do que um assento, uma cadeira ou parte de um objeto litúrgico do presbitério: é o reconhecimento de que a história da Igreja Católica, que passa de geração em geração, inicia-se na missão que Jesus deixa para Pedro, ao entregar a ele a autoridade sobre o seu povo.", source: "https://santo.cancaonova.com/santo/catedra-de-sao-pedro/?sDia=22&sMes=2&sAno=2025" },
  { day: 23, title: "Sao Policarpo, santo invocado como protetor dos ouvidos e das queimaduras", image: "/santos/2025/02-23.jpg", description: "Origens Grande padre apóstolo São Policarpo está entre os grandes padres apostólicos, ou seja, pertencia ao número daqueles que conviveram com os primeiros apóstolos e serviram de elo entre a Igreja primitiva e a Igreja do mundo greco-romano.", source: "https://santo.cancaonova.com/santo/sao-policarpo/?sDia=23&sMes=2&sAno=2025" },
  { day: 24, title: "Sao Sergio pagou com sua vida o combate a idolatria", image: "/santos/2025/02-24.jpg", description: "Contexto eclesial dos santos A Igreja Católica possui um documento oficial chamado Martirológio. E nele há uma relação oficial dos santos e beatos reconhecidos oficialmente. Por se tratar de um documento com informações dos primeiros séculos, em especial sobre essas, não existem tantos detalhes. Por exemplo, há vários santos com o nome “Sérgio”. Temos:", source: "https://santo.cancaonova.com/santo/sao-sergio/?sDia=24&sMes=2&sAno=2025" },
  { day: 25, title: "Santos Luis Versiglia e Calisto Caravario, santos salesianos", image: "/santos/2025/02-25.jpg", description: "Hoje, a Igreja celebra o dia de Santos Luís Versiglia e Calisto Caravario, santos salesianos de Dom Bosco, e Converteram multidões com grande zelo pastoral.", source: "https://santo.cancaonova.com/santo/luis-versiglia-e-calisto-caravario/?sDia=25&sMes=2&sAno=2025" },
  { day: 26, title: "Sao Porfirio, o restaurador da fe de um povo", image: "/santos/2025/02-26.jpg", description: "Origens São Porfírio era um tecelão, de família rica, nascido na Grécia. Aos 25 anos, decidiu viver de modo austero, dedicando-se à solidão e à penitência na região do Rio Jordão. Por causa de sua escolha, contraiu uma doença que o obrigou a mudar-se para Jerusalém, tornando-se mais moderado em sua austeridade. Mesmo doente, conta-se que ele não demonstrava sua realidade e se dedicava a visitar os lugares santos diariamente.", source: "https://santo.cancaonova.com/santo/sao-porfirio-o-restaurador-da-fe-de-um-povo/?sDia=26&sMes=2&sAno=2025" },
  { day: 27, title: "Sao Gabriel de Nossa Senhora das Dores, o santo do sorriso", image: "/santos/2025/02-27.jpg", description: "Origens Foi batizado em sua cidade natal, Assis (Itália), como Francisco Possenti. Tinha apenas 4 anos quando sua mãe morreu. Estudou em Colégios Católicos. Seu pai era governador do Estado Pontifício; e, por causa disso, ele mudava de cidade com frequência.", source: "https://santo.cancaonova.com/santo/sao-gabriel-de-nossa-senhora-das-dores/?sDia=27&sMes=2&sAno=2025" },
  { day: 28, title: "Santo Osvaldo, bispo", image: "/santos/2025/02-28.jpg", description: "A Igreja celebra em 29 de junho, Santo Osvaldo, bispo e confessor, homem de grande santidade, ativo, generoso e bom, Osvaldo apreciava também a ciência.", source: "https://santo.cancaonova.com/santo/santo-osvaldo-bispo/?sDia=28&sMes=2&sAno=2025" }
];

const marco: SantoDoDia[] = [
  { day: 1, title: "Santa Ines Cao Kuiying, mesmo engaiolada na China, nao negou a fe", image: "/santos/2025/03-01.jpg", description: "Origem Santa Inês Cao Kuiying nasceu numa aldeia chinesa. Ainda bem novinha, foi para um orfanato depois da morte de seus pais, que eram católicos.", source: "https://santo.cancaonova.com/santo/santa-ines-cao-kuiying/?sDia=1&sMes=3&sAno=2025" },
  { day: 2, title: "Santa Angela da Cruz superou o desprezo e fundou as Irmas da Cruz", image: "/santos/2025/03-02.jpg", description: "Origens Santa Ângela da Cruz é espanhola e de família com condição social modesta, mas repleta de virtudes cristãs. Ela cresceu em um ambiente muito religioso, ajudando os seus pais nos trabalhos manuais, principalmente na costura.", source: "https://santo.cancaonova.com/santo/santa-angela-da-cruz/?sDia=2&sMes=3&sAno=2025" },
  { day: 3, title: "Santa Catarina Drexel, amor a Eucaristia e servico aos indios e afro-americanos", image: "/santos/2025/03-03.jpg", description: "Origem Nasceu na Filadélfia (EUA). Filha de um famoso banqueiro, ela perdeu a mãe logo depois que nasceu e foi criada por seu pai e sua madrasta.", source: "https://santo.cancaonova.com/santo/santa-catarina-drexel/?sDia=3&sMes=3&sAno=2025" },
  { day: 4, title: "Sao Casimiro, que nao caiu nas seducoes do luxo e do poder", image: "/santos/2025/03-04.jpg", description: "Origens São Casimiro nasceu em 1458. Era o terceiro filho de Casimiro IV, o rei da Polônia e grão-duque da Lituânia, e sua esposa Isabel de Áustria. Na infância, teve como instrutor João Dugloss, bispo de Lemberg. Apresentou imediatamente boa aptidão para o estudo e disciplina, foram sobretudo as lições espirituais que ele aproveitou.", source: "https://santo.cancaonova.com/santo/sao-casimiro-que-nao-caiu-nas-seducoes-do-luxo-e-do-poder/?sDia=4&sMes=3&sAno=2025" },
  { day: 5, title: "Sao Joao Jose da Cruz: \"Tudo o que Deus permite, permite para o nosso bem\"", image: "/santos/2025/03-05.jpg", source: "https://santo.cancaonova.com/santo/sao-joao-jose-da-cruz-tudo-o-que-deus-permite-permite-para-o-nosso-bem/?sDia=5&sMes=3&sAno=2025" },
  { day: 6, title: "Santa Rosa de Viterbo, a jovem padroeira dos exilados", image: "/santos/2025/03-06.jpg", description: "Hoje, a Igreja celebra o dia de Santa Rosa de Viterbo, que foi uma jovem santa atraída pela espiritualidade franciscana e padroeira dos exilados.", source: "https://santo.cancaonova.com/santo/santa-rosa-de-viterbo/?sDia=6&sMes=3&sAno=2025" },
  { day: 7, title: "Santas Perpetua e Felicidade, martires do seculo II, protetoras das gravidas", image: "/santos/2025/03-07.jpg", description: "Origem Muitas mulheres, jovens, mães, foram martirizadas no ano 203, em Cartago (norte da África, atual cidade de Túnis). Dentre elas, Perpétua, que tinha aproximadamente 22 anos. Era nobre de família rica, sendo seu pai o único da família a ser pagão. Quando foi levada para a prisão, tinha um filho recém-nascido. Felicidade era escrava de Perpétua e, quando foi para a prisão, estava com oito meses de gestação e deu à luz uma menina neste lugar.", source: "https://santo.cancaonova.com/santo/santas-perpetua-e-felicidade/?sDia=7&sMes=3&sAno=2025" },
  { day: 8, title: "Sao Joao de Deus ensinou: \"Fazei bem, a vos mesmos, ajudando os pobres\"", image: "/santos/2025/03-08.jpg", source: "https://santo.cancaonova.com/santo/sao-joao-de-deus/?sDia=8&sMes=3&sAno=2025" },
  { day: 9, title: "Santa Francisca Romana, exemplo de caridade a toda prova", image: "/santos/2025/03-09.jpg", description: "Origens Francisca é filha de um casal cristão que, na fé católica, educou a criança. E quem imaginaria que aquela pequena menina teria um dos corações mais caridosos que a Cidade Eterna já viu? Desde a mais tenra idade, Francisca manifestou aos seus pais e à comunidade o seu amor pelas coisas de Deus. Imitava sua mãe nas práticas de piedade e devoção.", source: "https://santo.cancaonova.com/santo/santa-francisca-romana/?sDia=9&sMes=3&sAno=2025" },
  { day: 10, title: "Santa Maria Eugenia de Jesus agiu corajosamente na contramao", image: "/santos/2025/03-10.jpg", description: "Hoje, a Igreja celebra o dia de Santa Maria Eugênia de Jesus, que corajosamente agiu na contramão, Maria Eugênia de Jesus sonhou com a missão na China.", source: "https://santo.cancaonova.com/santo/santa-maria-eugenia-de-jesus-agiu-corajosamente-na-contramao/?sDia=10&sMes=3&sAno=2025" },
  { day: 11, title: "Santos Marcos Chong e Aleixo Se-yong, decapitados por seus parentes coreanos", image: "/santos/2025/03-11.jpg", description: "Igreja que nasce no martírio A história da Igreja é repleta de relatos de mártires, dentre eles, há uns mais conhecidos do que outros. Alguns nomes, como São Sebastião e Santa Luzia, são comuns entre os católicos. Outros mais recentes, como São Maximiliano Maria Kolbe, também são mais populares. Mas este texto pretende apresentar a você dois santos mártires, desconhecidos por muitos brasileiros, que, ao lado de outros, se tornaram verdadeiras bases da Igreja no Oriente: santos mártires Marcos Chong Ui-bae, catequista; e Aleixo U Se-yong, seu catequizando.", source: "https://santo.cancaonova.com/santo/santos-marcos-chong-e-aleixo-se-yong/?sDia=11&sMes=3&sAno=2025" },
  { day: 12, title: "Sao Luis Orione propagou: \"Fazer o bem sempre e a todos. O mal nunca e a ninguem\"", image: "/santos/2025/03-12.jpg", source: "https://santo.cancaonova.com/santo/sao-luis-orione/?sDia=12&sMes=3&sAno=2025" },
  { day: 13, title: "Santos Rodrigo e Salomao, homens com virtudes cristas", image: "/santos/2025/03-13.jpg", description: "Hoje, a Igreja celebra o dia dos Santos Rodrigo e Salomão, deram o testemunho de Cristo com as virtudes cristãs e, foram degolados por muçulmanos.", source: "https://santo.cancaonova.com/santo/santos-rodrigo-e-salomao-homens-com-virtudes-cristas/?sDia=13&sMes=3&sAno=2025" },
  { day: 14, title: "Santa Matilde da Alemanha exortava: \"Feliz quem prepara sua eterna salvacao\"", image: "/santos/2025/03-14.jpg", source: "https://santo.cancaonova.com/santo/santa-matilde-da-alemanha/?sDia=14&sMes=3&sAno=2025" },
  { day: 15, title: "Sao Clemente Maria Hofbauer foi padeiro e 2 fundador dos Redentoristas", image: "/santos/2025/03-15.jpg", description: "Origens São Clemente Maria Hofbauer nasceu, em 1751, em Tasswitz, na República Tcheca. Seus pais tiveram doze filhos, ele foi o nono filho dessa família muito simples e pobre. Somente recebeu o nome de Clemente quando se tornou eremita. Porém, seu nome de batismo era João.", source: "https://santo.cancaonova.com/santo/sao-clemente-maria-hofbauer-foi-padeiro-e-2o-fundador-dos-redentoristas/?sDia=15&sMes=3&sAno=2025" },
  { day: 16, title: "Santa Eusebia, viveu conforme seu nome  do grego, \"piedosa\"", image: "/santos/2025/03-16.jpg", source: "https://santo.cancaonova.com/santo/santa-eusebia-viveu-conforme-seu-nome-do-grego-piedosa/?sDia=16&sMes=3&sAno=2025" },
  { day: 17, title: "Sao Patricio da Irlanda e sua couraca - reze agora mesmo!", image: "/santos/2025/03-17.jpg", description: "Hoje, a Igreja celebra o dia de São Patrício da Irlanda, que foi quem escreveu \"A Couraça\" para invocar a proteção divina.", source: "https://santo.cancaonova.com/santo/sao-patricio/?sDia=17&sMes=3&sAno=2025" },
  { day: 18, title: "Sao Cirilo de Jerusalem, doutor da Igreja e principe dos catequistas", image: "/santos/2025/03-18.jpg", description: "Origens São Cirilo de Jerusalém nasceu por volta do ano de 315 em Jerusalém ou em seus arredores. Pouco se sabe sobre sua infância e juventude, além de que ele cresceu num lar cristão, com uma vida financeira confortável. Recebeu uma sólida formação nas Sagradas Escrituras e em matérias humanísticas.", source: "https://santo.cancaonova.com/santo/sao-cirilo-de-jerusalem/?sDia=18&sMes=3&sAno=2025" },
  { day: 19, title: "Sao Jose e sua solenidade - o patrono da Igreja Universal", image: "/santos/2025/03-19.jpg", description: "Origens Solenidade de São José, esposo da Santíssima Virgem Maria, homem justo, da descendência de David, que exerceu a missão de pai do Filho de Deus, Jesus Cristo, que quis ser chamado filho de José, e Jesus foi submisso como um filho ao seu pai. A Igreja venera, com especial honra, como seu patrono aquele a quem o Senhor constituiu chefe da sua família.", source: "https://santo.cancaonova.com/santo/sao-jose/?sDia=19&sMes=3&sAno=2025" },
  { day: 20, title: "Santa Maria Josefa, padroeira dos doentes e dos cuidadores", image: "/santos/2025/03-20.jpg", description: "Origens Maria Josefa do Coração de Jesus foi a primogênita de Barnabé Sancho, serralheiro, e de Petra de Guerra, doméstica. Nasceu na Espanha, dia 7 de setembro de 1842, e foi batizada no dia seguinte. Ficou órfã de pai muito cedo; e foi sua mãe quem a preparou para a primeira comunhão, recebida aos dez anos. Completou a sua formação e educação em Madri, na casa de alguns parentes e, desde muito cedo, começou a demonstrar uma grande devoção à Eucaristia e a Nossa Senhora. Também teve uma forte sensibilidade em relação aos pobres, aos doentes e uma inclinação para a vida interior.", source: "https://santo.cancaonova.com/santo/santa-maria-josefa/?sDia=20&sMes=3&sAno=2025" },
  { day: 21, title: "Sao Nicolau de Flue afirmava: a misericordia e maior que a justica", image: "/santos/2025/03-21.jpg", description: "Hoje, a Igreja celebra o dia de São Nicolau de Flüe afirmava: a misericórdia é maior que a justiça, alimentando-se apenas de Jesus na Eucaristia.", source: "https://santo.cancaonova.com/santo/sao-nicolau-de-flue/?sDia=21&sMes=3&sAno=2025" },
  { day: 22, title: "Sao Zacarias, Papa cujo nome significa \"o Senhor lembra\"", image: "/santos/2025/03-22.jpg", source: "https://santo.cancaonova.com/santo/sao-zacarias-papa/?sDia=22&sMes=3&sAno=2025" },
  { day: 23, title: "Sao Turibio de Mongrovejo, bispo corajoso que deixou um grande legado", image: "/santos/2025/03-23.jpg", description: "Origens Seu nome completo é Turíbio Alfonso de Mongrovejo. É espanhol e filho de uma família rica da nobreza. Estudou nas cidades de Santiago de Compostela, Valadolid e Salamanca. Formou-se advogado e participou da inquisição. Desde jovem, foi honesto e justo.", source: "https://santo.cancaonova.com/santo/sao-turibio-de-mongrovejo/?sDia=23&sMes=3&sAno=2025" },
  { day: 24, title: "Santa Catarina da Suecia, patrona das virgens e intercessora contra o aborto", image: "/santos/2025/03-24.jpg", description: "Hoje, a Igreja celebra o dia de Santa Catarina da Suécia, patrona das virgens e intercessora contra aborto, e Levou uma vida de muita oração.", source: "https://santo.cancaonova.com/santo/santa-catarina-da-suecia/?sDia=24&sMes=3&sAno=2025" },
  { day: 25, title: "Anunciacao do Senhor: o verdadeiro valor de um sim", image: "/santos/2025/03-25.jpg", description: "Origens Na história da existência, constantemente somos desafiados pela vida a darmos uma resposta ativa, consciente e madura ante os apelos e desafios que a nossa própria existência nos interpela. A todo instante, somos colocados em uma posição de escolha, entre aquilo que se quer e aquilo que não se quer; entre o possuir e o nada ter; entre o ser e o não ser.", source: "https://santo.cancaonova.com/santo/anunciacao-do-senhor/?sDia=25&sMes=3&sAno=2025" },
  { day: 26, title: "Sao Ludgero, obediente a Deus acima de tudo", image: "/santos/2025/03-26.jpg", description: "Formação Nasceu em 745, em Suescnom, na Frísia. Pertencia a uma família nobre. Desde criança, dedicou-se aos estudos e à vida religiosa. O empenhado São Ludgero foi formado como discípulo de São Gregório, no mosteiro, e, depois, de Alcuíno de York, reitor de uma escola muito famosa em sua época. Voltando à sua terra natal, Alberico suscitou-lhe o presbiterato, quando foi ordenado sacerdote em Colônia, no ano de 777.", source: "https://santo.cancaonova.com/santo/sao-ludgero-obediente-a-deus-acima-de-tudo/?sDia=26&sMes=3&sAno=2025" },
  { day: 27, title: "Sao Ruperto, o corajoso e memoravel Bispo de Salzburgo", image: "/santos/2025/03-27.jpg", description: "Origens São Ruperto descendia dos rupertinos, importante família que dominava com o título de conde a região do médio e do alto Reno. Dessa família nasceu também outro São Roberto (ou Ruperto) de Bingen, cuja vida foi escrita por Santa Hildegarda. Os rupertinos eram parentes dos carolíngios e o centro de suas atividades era em Worms. São Ruperto recebeu sua formação de cunho monástico irlandês.", source: "https://santo.cancaonova.com/santo/sao-ruperto/?sDia=27&sMes=3&sAno=2025" },
  { day: 28, title: "Sao Sebastiao Pelczar, em tudo serviu a Deus, por isso, se consumiu", image: "/santos/2025/03-28.jpg", description: "Origens José Sebastião Pelczar nasceu em 17 de janeiro de 1842, na Polônia. Cresceu e viveu a sua infância impregnado da religiosidade popular da casa dos seus pais. Desde criança já apresentava uma sabedoria diferenciada. E, ainda estudante, decidiu dedicar a vida ao serviço de Deus, e isso o conduziu até o último dia de sua vida.", source: "https://santo.cancaonova.com/santo/sao-sebastiao-pelczar/?sDia=28&sMes=3&sAno=2025" },
  { day: 29, title: "Sao Ludolfo, da Ordem Premonstratense e um exemplo de zelo pela Igreja", image: "/santos/2025/03-29.jpg", description: "Hoje, a Igreja celebra o dia de São Ludolfo, Como Bispo, enfrentou dificuldades em governar, da Ordem Premonstratense e um exemplo de zelo pela Igreja.", source: "https://santo.cancaonova.com/santo/sao-ludolfo/?sDia=29&sMes=3&sAno=2025" },
  { day: 30, title: "Sao Joao Climaco, em seu escondimento, atraiu tantos para Cristo", image: "/santos/2025/03-30.jpg", description: "Origens João nasceu na Síria em 579. Desde criança, demonstrou ser bem inteligente. Teve boa formação cristã e também literária. De família nobre e rica, com um futuro promissor na sociedade, ele preferia a simplicidade e a oração. Assim, aos 16 anos, sentiu-se chamado para a vida monástica eremítica.", source: "https://santo.cancaonova.com/santo/sao-joao-climaco/?sDia=30&sMes=3&sAno=2025" },
  { day: 31, title: "Sao Benjamim, o santo torturado com farpas embaixo das unhas", image: "/santos/2025/03-31.jpg", description: "Hoje, a Igreja celebra o dia de São Benjamim, que foi um santo torturado com farpas embaixo das unhas, martirizado por anunciar e testemunhar Cristo.", source: "https://santo.cancaonova.com/santo/sao-benjamim/?sDia=31&sMes=3&sAno=2025" }
];

const abril: SantoDoDia[] = [
  { day: 1, title: "Sao Ludovico Pavoni doou-se total e concretamente pelo jovens", image: "/santos/2025/04-01.jpg", description: "Origens Ludovico Pavoni nasceu em Bréscia (Itália), no dia 11 de setembro de 1784. Primeiro de cinco filhos, ele viveu em um tempo de mudanças políticas e sociais: a Revolução Francesa (1789), a Revolução Jacobina (1797), a dominação napoleônica com suas diversas denominações e, enfim, desde 1814, a dominação austríaca.", source: "https://santo.cancaonova.com/santo/sao-ludovico-pavoni/?sDia=1&sMes=4&sAno=2025" },
  { day: 2, title: "Sao Francisco de Paula, conhecido como \"O Eremita da Caridade\"", image: "/santos/2025/04-02.jpg", source: "https://santo.cancaonova.com/santo/sao-francisco-de-paula/?sDia=2&sMes=4&sAno=2025" },
  { day: 3, title: "Sao Luis Scrosoppi acompanha quem se entrega a Providencia de Deus", image: "/santos/2025/04-03.jpg", description: "Padroeiro Com a sua intercessão a favor dos pequenos, dos pobres, da juventude em dificuldade, das pessoas que sofrem, de quantos vivem situações penosas, também hoje, padre Luís continua a indicar para todos a estrada da união com Deus, da compaixão e do amor, além disso, está pronto para acompanhar os passos daqueles que se entregam à Providência de Deus.", source: "https://santo.cancaonova.com/santo/sao-luis-scrosoppi/?sDia=3&sMes=4&sAno=2025" },
  { day: 4, title: "Santo Isidoro, bispo, pai dos concilios e mestre da Igreja", image: "/santos/2025/04-04.jpg", description: "Hoje, a Igreja celebra o dia de Santo Isidoro, bispo, foi proclamado pelo Papa Bento XIV Santo de Sevilha Isidor, pai dos concílios e mestre da Igreja.", source: "https://santo.cancaonova.com/santo/santo-isidoro/?sDia=4&sMes=4&sAno=2025" },
  { day: 5, title: "Sao Vicente Ferrer, dominicano, maior pregador do seculo XIV", image: "/santos/2025/04-05.jpg", description: "Hoje, a Igreja celebra o dia de São Vicente Ferrer, dominicano, e por ser um pregador com um dom muito especial, começou a peregrinar por toda a Europa.", source: "https://santo.cancaonova.com/santo/sao-vicente-ferrer/?sDia=5&sMes=4&sAno=2025" },
  { day: 6, title: "Beato Miguel Rua, o primeiro salesiano e sucessor de Dom Bosco", image: "/santos/2025/04-06.jpg", description: "Hoje, a Igreja celebra o dia do Beato Miguel Rua, o primeiro salesiano e sucessor de Dom Bosco, sua vida totalmente atrelada à história de Dom Bosco.", source: "https://santo.cancaonova.com/santo/beato-miguel-rua/?sDia=6&sMes=4&sAno=2025" },
  { day: 7, title: "Sao Joao Batista de La Salle, patrono universal dos educadores", image: "/santos/2025/04-07.jpg", description: "Hoje, a Igreja celebra o dia de São João Batista de La Salle, o patrono universal dos educadores, e obtenção do título de doutor em teologia.", source: "https://santo.cancaonova.com/santo/sao-joao-batista-de-la-salle/?sDia=7&sMes=4&sAno=2025" },
  { day: 8, title: "Santa Julia Billiart, religiosa cujo alimento foi unicamente a Eucaristia", image: "/santos/2025/04-08.jpg", description: "Hoje, a Igreja celebra o dia de Santa Júlia Billiart, cujo o alimento foi unicamente a Eucaristia, fé viva na presença real de Jesus no Pão Eucarístico", source: "https://santo.cancaonova.com/santo/santa-julia-billiart/?sDia=8&sMes=4&sAno=2025" },
  { day: 9, title: "Beata Lindalva Justo de Oliveira, brasileira, martirizada aos 40 anos", image: "/santos/2025/04-09.jpg", description: "Origem Nascida em 20 de outubro de 1953, no povoado Sítio da Areia, no Rio Grande do Norte, no município de Açu. Lindalva foi a sexta filha de uma família formada por 14 irmãos e, ainda jovem, recebeu dos pais os ensinamentos da doutrina e da fé cristã. Com o pai, João Justo da Fé, Lindalva estudava as Sagradas Escrituras e participava da Santa Missa. Com a mãe, Maria Lúcia da Fé, aprendeu a cuidar de crianças, ajudar os pobres e realizar as tarefas da casa, sem deixar de lado os estudos. Lindalva foi batizada em 7 de janeiro de 1954 e recebeu a Primeira Eucaristia aos 12 anos.", source: "https://santo.cancaonova.com/santo/beata-lindalva-justo-de-oliveira/?sDia=9&sMes=4&sAno=2025" },
  { day: 10, title: "Santa Madalena de Canossa exclamava: facam conhecer a Jesus Cristo!", image: "/santos/2025/04-10.jpg", description: "Origens Madalena Gabriela de Canossa nasceu em Verona, no dia 1° de março de 1774, de família nobre e rica, terceira de seis irmãos. Com apenas cinco anos, ficou órfã de pai; dois anos depois, foi abandonada pela mãe, que recasou com o marquês Zenetti de Mântua. A educação de Madalena de Canossa e de seus quatro irmãos foi confiada, nos anos seguintes, a uma governanta francesa, bastante severa, que não compreendendo o caráter da menina, a tratava com excessiva dureza.", source: "https://santo.cancaonova.com/santo/santa-madalena-de-canossa/?sDia=10&sMes=4&sAno=2025" },
  { day: 11, title: "Santa Gema Galgani, a virgem intercessora dos farmaceuticos", image: "/santos/2025/04-11.jpg", description: "Origens Gemma, conforme nome original em italiano, teve uma curta existência nesta terra. Nasceu em Camigliano, na Toscana, em 1878, e morreu em Lucca, aos 25 anos. É uma história de fervorosa piedade, de caridade e de contínuos sofrimentos.", source: "https://santo.cancaonova.com/santo/santa-gema-galgani/?sDia=11&sMes=4&sAno=2025" },
  { day: 12, title: "Sao Jose Moscati, medico intimo de Deus, caridoso, casto, trabalhador e despojado", image: "/santos/2025/04-12.jpg", description: "Origens Entre as estrelas de primeira grandeza do século XX conta-se São José Moscati. Nasceu no dia 25 de julho de 1880 em Benevento, Itália, sétimo de nove filhos do casal Francisco Moscati, presidente do tribunal daquela cidade, Rosaria de Luca, descendente dos marqueses de Roseto. Seus pais eram católicos praticantes. Tanto que José Moscati foi batizado em sua casa no dia da festa de Santo Inácio de Loyola.", source: "https://santo.cancaonova.com/santo/sao-jose-moscati/?sDia=12&sMes=4&sAno=2025" },
  { day: 13, title: "Santa Margarida, cega, abandonada pelos pais, tornou-se religiosa", image: "/santos/2025/04-13.jpg", description: "Origem Margarida nasceu numa família nobre por volta do ano de 1287, em Urbino, Itália. Cega e com uma deformação física, seus pais tinham vergonha de apresentá-la ao mundo. Então, ela viveu cerca de cinco anos no escondimento, dentro de uma cela, onde foi educada com princípios cristãos.", source: "https://santo.cancaonova.com/santo/santa-margarida/?sDia=13&sMes=4&sAno=2025" },
  { day: 14, title: "Santa Ludovina, invocada como intercessora dos doentes cronicos", image: "/santos/2025/04-14.jpg", description: "Infância caridosa Ainda quando criança, Ludovina recolhia alimentos e roupas para doar aos pobres e doentes. Foi uma jovem viva, eficaz e cheia de brincadeiras.", source: "https://santo.cancaonova.com/santo/santa-ludovina/?sDia=14&sMes=4&sAno=2025" },
  { day: 15, title: "Sao Damiao de Veuster, patrono espiritual dos leprosos e marginalizados", image: "/santos/2025/04-15.jpg", description: "Hoje, a Igreja celebra o dia de São Damião de Veuster, Foi ordenado sacerdote e partiu numa viagem, e é patrono espiritual dos leprosos e marginalizados.", source: "https://santo.cancaonova.com/santo/sao-damiao-de-veuster/?sDia=15&sMes=4&sAno=2025" },
  { day: 16, title: "Santa Maria Bernadete, intima da Virgem Maria e imitadora de Suas virtudes", image: "/santos/2025/04-16.jpg", description: "Naturalidade Nascida em 7 de janeiro de 1844, em Lourdes, sudeste da França, aos pés dos montes Pirineus, Bernadete viveu em grande pobreza, mas sempre com o coração dirigido a Maria.", source: "https://santo.cancaonova.com/santo/santa-maria-bernadete/?sDia=16&sMes=4&sAno=2025" },
  { day: 17, title: "Santa Catarina Tekakwitha, indigena crista na America do Norte", image: "/santos/2025/04-17.jpg", description: "Hoje, a Igreja celebra o dia de Santa Catarina Tekakwitha, que é uma indígena cristã na América do Norte, amava Jesus e obedecia à moral cristã.", source: "https://santo.cancaonova.com/santo/santa-catarina-tekakwitha/?sDia=17&sMes=4&sAno=2025" },
  { day: 18, title: "Sao Galdino, cardeal caridoso que defendeu a fe e serviu aos pobres", image: "/santos/2025/04-18.jpg", description: "Origens!! Nascido em Milão (Itália) no ano de 1096, São Galdino foi um religioso com uma rápida ascensão diretamente de auxiliar para bispo de sua cidade. São Galdino ficou conhecido por enfrentar o antipapa Vítor IV, que era apoiado pelo Frederico, o Barbaroxa, que arrasou a cidade de Milão no ano de 1162 por sua oposição.", source: "https://santo.cancaonova.com/santo/sao-galdino/?sDia=18&sMes=4&sAno=2025" },
  { day: 19, title: "Sao Leao IX, 152 Papa da Igreja Catolica, exemplo de defesa a Igreja", image: "/santos/2025/04-19.jpg", description: "Origem! São Leão IX, Brunone dos Condes de Egisheim, seu nome de Batismo, nasceu em Eguisheim, região da Alsácia (território francês). Pertencia a uma família de grandes vassalos (classe do período medieval, responsável por servir aos seus senhores feudais).", source: "https://santo.cancaonova.com/santo/sao-leao-ix/?sDia=19&sMes=4&sAno=2025" },
  { day: 20, title: "Santa Ines de Montepulciano, tornou prostitutas em freiras", image: "/santos/2025/04-20.jpg", description: "Origem Italiana, nasceu numa aldeia chamada Graciano, vizinha da cidade de Montepulciano. Filha de uma rica família chamada Segni, aos 4 anos já sabia rezar as orações do Pai-Nosso e Ave-Maria. Desde os seis anos, disse aos pais que queria se tornar freira, eles porém, não aceitavam.", source: "https://santo.cancaonova.com/santo/santa-ines-de-montepulciano/?sDia=20&sMes=4&sAno=2025" },
  { day: 21, title: "Santo Anselmo, bispo da Cantuaria e Doutor da Igreja", image: "/santos/2025/04-21.jpg", description: "Origens Nasceu em Piamonte no ano de 1033. Seu pai era Conde Gondulfo e a senhora Ermemberga, que garantiu uma educação baseada nos valores cristãos. Santo Anselmo, teve como mestre um clérigo e depois foi educado pelos beneditinos, fazendo com que desperta-se o desejo de viver uma vida contemplativa. Contudo, devido ao mau relacionamento com ele, saiu de casa, apenas com um burrinho e um servo se dirigindo para França.", source: "https://santo.cancaonova.com/santo/santo-anselmo/?sDia=21&sMes=4&sAno=2025" },
  { day: 22, title: "Santa Senhorinha, modelo de oracao, contemplacao e trabalho", image: "/santos/2025/04-22.jpg", description: "Hoje, a Igreja celebra o dia de Santa Senhorinha, canonizada santa pela Igreja Católica em 1130, abadessa, modelo de oração, contemplação e trabalho.", source: "https://santo.cancaonova.com/santo/santa-senhorinha/?sDia=22&sMes=4&sAno=2025" },
  { day: 23, title: "Sao Jorge, o santo comparado a Sao Miguel no Oriente", image: "/santos/2025/04-23.jpg", description: "Origens São Jorge, cujo nome de origem grega significa “agricultor”, nasceu na Capadócia, por volta do ano 280, em uma família cristã. Transferiu-se para a Palestina, onde se alistou no exército de Diocleciano. Em 303, quando o imperador emanou um edito para a perseguição dos cristãos, Jorge doou todos os seus bens aos pobres e, diante de Diocleciano, rasgou o documento e professou a sua fé em Cristo. Por isso, sofreu terríveis torturas e, no fim, foi decapitado.", source: "https://santo.cancaonova.com/santo/sao-jorge/?sDia=23&sMes=4&sAno=2025" },
  { day: 24, title: "Santa Maria Isabel Hesselblad e seu retorno a fe catolica", image: "/santos/2025/04-24.jpg", description: "Origem Maria Isabel Hesselblad nasceu em Faglavik, Suécia, em 1870, em uma família de fé luterana, vivida de modo diário e concreto. Desde a escola primária, pelo seu sensível grau de observação, notava que seus colegas de classe professavam as crenças cristãs mais diversas, mas achava que não deveria ser assim. Por isso, começou a pôr-se em busca da única Verdade.", source: "https://santo.cancaonova.com/santo/santa-maria-isabel-hesselblad/?sDia=24&sMes=4&sAno=2025" },
  { day: 25, title: "Sao Marcos, o primeiro a escrever os ensinamentos de Jesus", image: "/santos/2025/04-25.jpg", description: "Hoje, a Igreja celebra o dia de São Marcos, que foi o primeiro a escrever os ensinamentos de Jesus e Marcos foi fiel discípulo de São Pedro.", source: "https://santo.cancaonova.com/santo/sao-marcos/?sDia=25&sMes=4&sAno=2025" },
  { day: 26, title: "Sao Rafael Arnaiz Baron: um jovem santo, alegre e monge trapista", image: "/santos/2025/04-26.jpg", description: "Origens Filho de Rafael Arnaiz e de Mercedes Báron, primeiro de quatro filhos de uma família católica, artista, pintor, poeta e violinista. Seus pais reconheceram suas habilidades artísticas e, aos 15 anos, deram-lhe de presente aulas de desenho. Isso o motivou a cursar arquitetura.", source: "https://santo.cancaonova.com/santo/sao-rafael-arnaiz-baron/?sDia=26&sMes=4&sAno=2025" },
  { day: 27, title: "Santa Zita, virgem e padroeira das empregadas domesticas", image: "/santos/2025/04-27.jpg", description: "Origens Nasceu em 1218, no povoado de Monsagrati, perto da cidade de Lucca (Itália). Era de uma família pobre, numerosa e camponesa, mas recebeu a riqueza da vida em Deus em seus ensinamentos.", source: "https://santo.cancaonova.com/santo/santa-zita/?sDia=27&sMes=4&sAno=2025" },
  { day: 28, title: "Sao Luis Maria de Montfort e o tratado da verdadeira devocao", image: "/santos/2025/04-28.jpg", description: "Hoje, a Igreja celebra o dia de São Luís Maria de Montfort, que escreveu o tratado da verdadeira devoção, influencia ainda hoje, muitos filhos de Maria.", source: "https://santo.cancaonova.com/santo/sao-luis-maria-de-montfort/?sDia=28&sMes=4&sAno=2025" },
  { day: 29, title: "Santa Catarina de Sena, voz de Deus e doutora da Igreja", image: "/santos/2025/04-29.jpg", description: "Origens Catarina nasceu em Siena, Itália, em 25 de março de 1347. Ela foi a 24ª filha de um tintureiro chamado Giacomo de Benincasa. Desde pequena, dedicou a sua infância a Deus. Fez parte da Ordem Terceira de São Domingos.", source: "https://santo.cancaonova.com/santo/santa-catarina-de-sena/?sDia=29&sMes=4&sAno=2025" },
  { day: 30, title: "Sao Pio V, Papa devoto de Nossa Senhora, a Rainha das Batalhas", image: "/santos/2025/04-30.jpg", description: "Hoje, a Igreja celebra o dia de São Pio V, papa devoto de Nossa Senhora, a Rainha das Batalhas, São Pio V foi beatificado pelo Papa Clemente X.", source: "https://santo.cancaonova.com/santo/sao-pio-v/?sDia=30&sMes=4&sAno=2025" }
];

const maio: SantoDoDia[] = [
  { day: 1, title: "Sao Jose, o operario de Nazare que ensina santificar o trabalho", image: "/santos/2025/05-01.jpg", description: "Hoje, a Igreja celebra o dia de São José Operário, que é pai do menino Jesus e exemplo de santidade, humilde e foi um grande artesão de Nazaré.", source: "https://santo.cancaonova.com/santo/sao-jose-o-operario-de-nazare-que-ensina-santificar-o-trabalho/?sDia=1&sMes=5&sAno=2025" },
  { day: 2, title: "Santo Atanasio, bispo de Alexandria no Egito e doutor da Igreja", image: "/santos/2025/05-02.jpg", description: "Hoje, a Igreja celebra o dia de Santo Atanásio, que é um dos doutores da Igreja. Quantos jovens, vendo seu exemplo, abraçaram a vida monástica.", source: "https://santo.cancaonova.com/santo/santo-atanasio-bispo-de-alexandria-no-egito-e-doutor-da-igreja/?sDia=2&sMes=5&sAno=2025" },
  { day: 3, title: "Sao Filipe e Sao Tiago, discipulos e apostolos escolhidos pessoalmente por Jesus", image: "/santos/2025/05-03.jpeg", description: "A Igreja celebra em 3 de maio os apóstolos São Filipe e São Tiago, companheiros leais de Jesus, escolhidos para propagar o Evangelho por todo o mundo.", source: "https://santo.cancaonova.com/santo/sao-filipe-e-sao-tiago-discipulos-e-apostolos-escolhidos-pessoalmente-por-jesus/?sDia=3&sMes=5&sAno=2025" },
  { day: 4, title: "Santa Antonina de Niceia, martirizada com ferros em brasa por ser crista", image: "/santos/2025/05-04.jpg", description: "Antonina é o feminino do antigo nome latino Antonius, derivado, provavelmente, do grego Antionos, que significa “nascido antes”. É um dos nomes mais difundidos entre os povos latinos, que ganhou muitos adeptos entre os cristãos. Mas, antes de Cristo, era muito comum também.", source: "https://santo.cancaonova.com/santo/santa-antonina-de-niceia-martirizada-com-ferros-em-brasa-por-ser-crista/?sDia=4&sMes=5&sAno=2025" },
  { day: 5, title: "Beato Gregorio Frackowiak, martir guilhotinado por amor aos irmaos e a Cristo", image: "/santos/2025/05-05.jpg", description: "A Igreja celebra em 5 de maio o Beato Gregório Frackowiak, religioso da Sociedade do Verbo Divino e mártir que com um golpe da guilhotina morreu por Cristo.", source: "https://santo.cancaonova.com/santo/beato-gregorio-frackowiak-martir-guilhotinado-por-amor-aos-irmaos-e-a-cristo/?sDia=5&sMes=5&sAno=2025" },
  { day: 6, title: "Sao Domingos Savio, padroeiro dos adolescentes e das mulheres gravidas", image: "/santos/2025/05-06.jpg", description: "São Domingos Sávio, que, dotado de ânimo afável e jovial já desde a infância, ainda adolescente percorreu velozmente o caminho da perfeição cristã.", source: "https://santo.cancaonova.com/santo/sao-domingos-savio-padroeiro-dos-adolescentes-e-das-mulheres-gravidas/?sDia=6&sMes=5&sAno=2025" },
  { day: 7, title: "Beato Francisco Paleari, um amigo simples e caridoso do ceu", image: "/santos/2025/05-07.jpg", description: "Família Francisco Paleari nasceu em Pogliano Milanese, na arquidiocese de Milão, em 22 de outubro de 1863, penúltimo de oito filhos. Sua família carecia de recursos financeiros e não podia enviar o jovem ao seminário diocesano. No entanto, pôde cumprir a sua vocação sacerdotal em Turim, na Pequena Casa da Providência.", source: "https://santo.cancaonova.com/santo/beato-francisco-paleari-um-amigo-simples-e-caridoso-do-ceu/?sDia=7&sMes=5&sAno=2025" },
  { day: 8, title: "Beata Ulrica, exemplo de humildade, servico e misericordia", image: "/santos/2025/05-08.jpg", description: "Síntese Virgem das Irmãs da Caridade da Santa Cruz, que nos mais humildes serviços, sobretudo nas tarefas de ajudante de cozinha, mostrou-se incansável serva do Senhor.", source: "https://santo.cancaonova.com/santo/beata-ulrica-exemplo-de-humildade-servico-e-misericordia/?sDia=8&sMes=5&sAno=2025" },
  { day: 9, title: "Beato Estevao Grelewski, martir e apostolo fervoroso dos nossos dias", image: "/santos/2025/05-09.jpg", description: "Estêvão Grelewski Nasceu na comuna de Dwikozy, centro-sul da Polonia, em 1899. Tornou-se sacerdote no ano de 1921 e, em 1924, obteve doutorado em direito canônico na universidade de Estrasburgo, França.", source: "https://santo.cancaonova.com/santo/beato-estevao-grelewski-martir-e-apostolo-fervoroso-dos-nossos-dias/?sDia=9&sMes=5&sAno=2025" },
  { day: 10, title: "Sao Joao de Avila, doutor da Igreja e o santo amigo de santos", image: "/santos/2025/05-10.jpg", description: "A Igreja celebra em 10 de maio, São João de Ávila, doutor da Igreja espanhol e o santo amigo de santos, sendo contemporâneo de vários deles.", source: "https://santo.cancaonova.com/santo/sao-joao-de-avila-doutor-da-igreja-e-o-santo-amigo-de-santos/?sDia=10&sMes=5&sAno=2025" },
  { day: 11, title: "Beato Zeferino Namuncura, modelo salesiano de santidade", image: "/santos/2025/05-11.jpg", description: "A Igreja celebra em 11 de maio o Beato Zeferino Namuncurá, indígena, aspirante ao sacerdócio e salesiano que tinha Domingos Sávio como referência.", source: "https://santo.cancaonova.com/santo/beato-zeferino-namuncura-modelo-salesiano-de-santidade/?sDia=11&sMes=5&sAno=2025" },
  { day: 12, title: "Santos Nereu, Aquiles e Pancracio, martires", image: "/santos/2025/05-12.jpg", description: "“Todas as estradas levam para Roma”, diz um provérbio, e de Roma saem algumas das mais célebres estradas do mundo. Em duas dessas estradas, a sudeste e oeste, a Ardeatina e a Aurélia, foram sepultados os mártires Nereu, Aquiles e Pancrácio. Embora recordados os três no mesmo dia, 12 de maio, o culto deles foi sempre separado, como dizem os compiladores do novo calendário: “A memória dos santos Nereu e Aquiles e a memória de são Pancrácio são celebradas separadamente com formulários próprios segundo uma antiga tradição romana. Ao contrário, a memória de santa Domitila, introduzida no Calendário romano em 1595, deve ser cancelada, pois o seu culto não encontra fundamento algum na tradição”. Isso resolve também a questão da época em que Nereu e Aquiles deram seu testemunho.", source: "https://santo.cancaonova.com/santo/santos-nereu-aquiles-e-pancracio-martires/?sDia=12&sMes=5&sAno=2025" },
  { day: 13, title: "Santa Maria Domingas Mazzarello, fundadora das Filhas de Maria Auxiliadora", image: "/santos/2025/05-13.jpg", description: "A Igreja celebra, em 13 de maio, Santa Maria Domingas Mazzarello. Ela foi contemporânea de Dom Bosco e fundadora das Filhas de Maria Auxiliadora.", source: "https://santo.cancaonova.com/santo/santa-maria-domingas-mazzarello-fundadora-das-filhas-de-maria-auxiliadora/?sDia=13&sMes=5&sAno=2025" },
  { day: 14, title: "Sao Matias, apostolo e martir, testemunho vivo da ressurreicao de Jesus", image: "/santos/2025/05-14.jpg", description: "Nome e eleição Matias é nome frequente entre os judeus e quer dizer “dom de Deus”. É o apóstolo que recebeu o dom do grande privilégio de ser agregado aos Doze, tomando o lugar vago deixado pela deserção de Judas Iscariotes. Sua eleição foi mediante sorteio, após a ascensão do Senhor, pela proposta de Simão Pedro, que, em poucas palavras, fixou os três requisitos para o ministério apostólico: pertencer aos que seguiam Jesus desde o começo, ser chamado e enviado: “É necessário, pois, que, destes homens que nos acompanharam durante todo o tempo em que o Senhor Jesus viveu no meio de nós, a começar pelo batismo de João até ao dia em que nos foi arrebatado, haja um que se torne conosco testemunha de sua ressurreição”. Essa foi uma das condições necessárias: Ser testemunha ocular do ressuscitado!", source: "https://santo.cancaonova.com/santo/sao-matias-apostolo-e-martir-testemunho-vivo-da-ressurreicao-de-jesus/?sDia=14&sMes=5&sAno=2025" },
  { day: 15, title: "Santo Isidoro, o Lavrador, conhecido como padroeiro dos camponeses e agricultores", image: "/santos/2025/05-15.jpg", description: "A Igreja celebra em 15 de maio, Santo Isidoro agricultor, um leigo que, após sua santificação, ficou conhecido como padroeiro dos camponeses e agricultores.", source: "https://santo.cancaonova.com/santo/santo-isidoro-o-lavrador-conhecido-como-padroeiro-dos-camponeses-e-agricultores/?sDia=15&sMes=5&sAno=2025" },
  { day: 16, title: "Beato Vital Vladimiro Bajrak, ucraniano perseguido e morto pelos sovieticos", image: "/santos/2025/05-16.jpg", description: "A Igreja celebra, em 16 de maio, o Beato Vital Vladimiro Bajrak, presbítero da Ordem de São Josafat e mártir pelo combate da fé alcançou o céu.", source: "https://santo.cancaonova.com/santo/beato-vital-vladimiro-bajrak-ucraniano-perseguido-e-morto-pelos-sovieticos/?sDia=16&sMes=5&sAno=2025" },
  { day: 17, title: "Sao Pedro Liu Wenyuan, catequista chines estrangulado por seguir Jesus", image: "/santos/2025/05-17.jpg", description: "A Igreja celebra, em 17 de maio, São Pedro Liu Wenyuan, um catequista chinês, pai de família, que foi estrangulado por seguir Jesus e não negar a sua fé.", source: "https://santo.cancaonova.com/santo/sao-pedro-liu-wenyuan-catequista-chines-estrangulado-por-seguir-jesus/?sDia=17&sMes=5&sAno=2025" },
  { day: 18, title: "Sao Leonardo Murialdo, salesiano e fundador da Congregacao de Sao Jose", image: "/santos/2025/05-18.jpg", description: "Realidade familiar Leonardo Murialdo nasceu no dia 26 de outubro de 1828, na cidade de Turim, na Itália. Aos cinco anos, já era órfão de pai. A família era abastada, numerosa, profundamente cristã e muito tradicional em Turim, sua cidade natal. Isso lhe garantiu uma boa formação acadêmica e religiosa.", source: "https://santo.cancaonova.com/santo/sao-leonardo-murialdo-salesiano-e-fundador-da-congregacao-de-sao-jose/?sDia=18&sMes=5&sAno=2025" },
  { day: 19, title: "Santa Maria Bernarda, missionaria caridosa na America do Sul", image: "/santos/2025/05-19.jpg", description: "A Igreja celebra em 19 de maio Santa Maria Bernarda, que tem o título de a missionária caridosa na América do Sul e que serve de exemplo para todos nós.", source: "https://santo.cancaonova.com/santo/santa-maria-bernarda-missionaria-caridosa-na-america-do-sul/?sDia=19&sMes=5&sAno=2025" },
  { day: 20, title: "Sao Bernardino de Sena, pregador e padroeiro dos publicitarios", image: "/santos/2025/05-20.jpeg", description: "Bernardino de Sena Nasceu na Itália no ano de 1380. Aos três anos, ficou órfão de mãe e, aos 7 anos, ficou órfão de pai. O jovem Bernardino foi criado pelas tias as quais o ensinaram sobre a devoção a Nossa Senhora e a Jesus Cristo. Teve uma boa educação na fé e nos seus ensinamentos, estudou na universidade de Sena e, aos 22 anos, decidiu abandonar tudo e entrar para a ordem dos Franciscanos.", source: "https://santo.cancaonova.com/santo/sao-bernardino-de-sena-pregador-e-padroeiro-dos-publicitarios/?sDia=20&sMes=5&sAno=2025" },
  { day: 21, title: "Beatos Padre Manuel Gonzalez e seu coroinha, Adilio Daronch, fuzilados no Brasil", image: "/santos/2025/05-21.jpg", description: "A Igreja celebra, em 21 de maio, Beatos Padre Manuel González e seu coroinha, Adílio Daronch, que foram fuzilados no Brasil por seu testemunho a Cristo.", source: "https://santo.cancaonova.com/santo/beatos-padre-manuel-gonzalez-e-seu-coroinha-adilio-daronch-fuzilados-no-brasil/?sDia=21&sMes=5&sAno=2025" },
  { day: 22, title: "Santa Rita de Cassia, intercessora das familias e das causas impossiveis", image: "/santos/2025/05-22.jpg", description: "A Igreja celebra em 22 de maio Santa Rita de Cássia que é intercessora das famílias e das causas impossíveis. Santa Rita de Cássia, rogai por nós!", source: "https://santo.cancaonova.com/santo/santa-rita-de-cassia-intercessora-das-familias-e-das-causas-impossiveis/?sDia=22&sMes=5&sAno=2025" },
  { day: 23, title: "Sao Joao Batista de Rossi, presbitero do aconselhamento", image: "/santos/2025/05-23.jpg", description: "João Batista de Rossi fundou a “Pia União de Sacerdotes Seculares”, que foi dirigida por ele durante alguns anos. Como desejava obras ainda mais abundantes, também fundou e dirigiu a Casa de Santa Gala, destinada para homens carentes e, depois, a Casa de São Luiz Gonzaga, para mulheres necessitadas.", source: "https://santo.cancaonova.com/santo/sao-joao-batista-de-rossi-presbitero-do-aconselhamento/?sDia=23&sMes=5&sAno=2025" },
  { day: 24, title: "Nossa Senhora Auxiliadora, a patrona da Cancao Nova e devocao de Dom Bosco", image: "/santos/2025/05-24.jpg", description: "A Igreja celebra, em 24 de maio, Nossa Senhora Auxiliadora, declarado por Monsenhor Jonas Abib a patrona da Canção Nova, com a devoção vinda de Dom Bosco.", source: "https://santo.cancaonova.com/santo/nossa-senhora-auxiliadora-a-patrona-da-cancao-nova-e-devocao-de-dom-bosco/?sDia=24&sMes=5&sAno=2025" },
  { day: 25, title: "Santa Maria Madalena de Pazzi, virgem e religiosa carmelita", image: "/santos/2025/05-25.jpg", description: "Catarina, nome recebido em seu batismo, nasceu em Florença, na Itália, no dia 2 de abril de 1566. Desde pequena, o seu amor por Cristo e pela Santíssima Virgem eram visíveis: agarrava-se à sua mãe com extraordinário ardor quando esta voltava para casa após ter comungado, mas se ela não comungara, sua filha não tinha as mesmas expansões.", source: "https://santo.cancaonova.com/santo/santa-maria-madalena-de-pazzi-virgem-e-religiosa-carmelita/?sDia=25&sMes=5&sAno=2025" },
  { day: 26, title: "Sao Filipe Neri, o santo da alegria, oracao, penitente e adorador", image: "/santos/2025/05-26.jpg", description: "A Igreja celebra em 26 de maio São Filipe Néri, homem de oração, penitência e adoração; mesmo antes de ser padre, visitava os lugares mais pobres de Roma.", source: "https://santo.cancaonova.com/santo/sao-filipe-neri-o-santo-da-alegria-oracao-penitente-e-adorador/?sDia=26&sMes=5&sAno=2025" },
  { day: 27, title: "Santo Agostinho de Cantuaria, monge e missionario", image: "/santos/2025/05-27.jpg", description: "A Igreja celebra, em 27 de maio, Santo Agostinho, que, na Grã-Bretanha, exerceu santamente sua missão de levar muitos à santidade e assim santificar-se.", source: "https://santo.cancaonova.com/santo/santo-agostinho-de-cantuaria-monge-e-missionario/?sDia=27&sMes=5&sAno=2025" },
  { day: 28, title: "Sao Germano de Paris, bispo, homem de oracao e escuta", image: "/santos/2025/05-28.jpg", description: "A Igreja celebra, em 28 de maio, São Germano, homem de oração e escuta, dócil e pronto para renunciar a si mesmo e optar pelo querer de Deus.", source: "https://santo.cancaonova.com/santo/sao-germano-de-paris-bispo-homem-de-oracao-e-escuta/?sDia=28&sMes=5&sAno=2025" },
  { day: 29, title: "Santa Ursula Ledochowska, virgem e fundadora", image: "/santos/2025/05-29.jpg", description: "A Igreja celebra, em 29 de maio, Santa Úrsula Ledóchowska, que trabalhou em favor dos africanos oprimidos pela escravidão e fundou uma Congregação.", source: "https://santo.cancaonova.com/santo/santa-ursula-ledochowska-virgem-e-fundadora/?sDia=29&sMes=5&sAno=2025" },
  { day: 30, title: "Santa Joana d'Arc: camponesa, guerreira e santa", image: "/santos/2025/05-30.jpg", description: "A Igreja celebra, em 30 de maio, Santa Joana com um exército de cinco mil soldados, estabelecendo várias vitórias, com oração e sem uma só gota de sangue.", source: "https://santo.cancaonova.com/santo/santa-joana-darc-camponesa-guerreira-e-santa/?sDia=30&sMes=5&sAno=2025" },
  { day: 31, title: "Visitacao de Nossa Senhora, o encontro de duas promessas", image: "/santos/2025/05-31.jpg", description: "Nossa Senhora foi visitada pelo Arcanjo Gabriel com uma mensagem de amor: a proposta de fazer dela a Mãe do nosso Salvador. E ela aceitou. Aceitar Jesus é estar aberto a aceitar, receber e doar-se aos outros.", source: "https://santo.cancaonova.com/santo/visitacao-de-nossa-senhora-o-encontro-de-duas-promessas/?sDia=31&sMes=5&sAno=2025" }
];

